import base64, hashlib, json, shutil, subprocess, sys, zlib
PATH = "/kaggle/working/cv/notebooks/path_b_eval.py"
EXPECT_SHA = "6889d4fce884657ad7377a3647840686a345236fb4ca8b4dff7f53e6d3397a1f"
PATCH = ""

text = open(PATH, encoding="utf-8", newline="").read().replace("\r\n", "\n")
if "PIPELINE_STAGES" in text:
    raise SystemExit("already patched - nothing to do")
if hashlib.sha256(text.encode("utf-8")).hexdigest() != EXPECT_SHA:
    raise SystemExit("the Kaggle copy is not the version this patch was made against; use the full-file route instead")
pairs = json.loads(zlib.decompress(base64.b64decode(PATCH)))
for old, new in pairs:
    assert text.count(old) == 1, "hunk does not match exactly once"
    text = text.replace(old, new)
shutil.copy(PATH, PATH + ".bak")
open(PATH, "w", encoding="utf-8", newline="\n").write(text)
print(f"applied {len(pairs)} hunks; backup at {PATH}.bak")
subprocess.run([sys.executable, "-m", "py_compile", PATH], check=True)
print("compiles OK")
